package com.huy.enterprise.order; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/purchase-orders") @RequiredArgsConstructor public class PurchaseOrderController {private final PurchaseOrderService service;@GetMapping List<OrderResponse> all(){return service.all();}@GetMapping("/{id}") OrderResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) OrderResponse create(@Valid @RequestBody OrderRequest r){return service.save(null,r);}@PutMapping("/{id}") OrderResponse update(@PathVariable UUID id,@Valid @RequestBody OrderRequest r){return service.save(id,r);}@PatchMapping("/{id}/status") OrderResponse status(@PathVariable UUID id,@Valid @RequestBody OrderStatusRequest r){return service.status(id,r);}}
